effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = src.a;
  float l = gmLum(src.rgb / max(a, 1e-4));
  float o = depth * (l - 0.5) * 2.0 * mixAmt;
  if (swap) o = -o;
  float r = texture2DCv(inputImg.texture, uv + vec2(o, 0.0)).r;
  float gb = texture2DCv(inputImg.texture, uv - vec2(o, 0.0)).g;
  float bb = texture2DCv(inputImg.texture, uv - vec2(o, 0.0)).b;
  gl_FragColor = vec4(r, gb, bb, a);
}
